import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> lines = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            lines.add(sc.nextLine());
        }
        ValidationRule longEnough = s -> s.length() >= 5;
        ValidationRule alphanumeric = s -> s.chars().allMatch(c ->
                (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'));
        ValidationRule valid = longEnough.and(alphanumeric);
        StringBuilder out = new StringBuilder();
        for (String name : lines) {
            out.append(valid.test(name) ? "VALID" : "INVALID").append("\n");
        }
        System.out.print(out);
    }
}

@FunctionalInterface
interface ValidationRule {
    boolean test(String value);

    default ValidationRule and(ValidationRule other) {
        return value -> this.test(value) && other.test(value);
    }
}

