import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int k = Integer.parseInt(sc.next());
        List<String[]> records = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            records.add(new String[] {sc.next(), sc.next()});
        }
        Map<String, Long> totals = records.stream()
                .collect(Collectors.groupingBy(r -> r[0], Collectors.summingLong(r -> Long.parseLong(r[1]))));
        Comparator<Map.Entry<String, Long>> byTotal = Comparator.comparing(Map.Entry::getValue);
        Comparator<Map.Entry<String, Long>> ranking = byTotal.reversed().thenComparing(Map.Entry::getKey);
        String report = totals.entrySet().stream()
                .sorted(ranking)
                .limit(k)
                .map(e -> e.getKey() + ": " + e.getValue())
                .collect(Collectors.joining("\n"));
        System.out.println(report);
    }
}
